/* @autogenerated */
package net.civeira.phylax.features.notification.outbox.application.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Observes;
import jakarta.enterprise.event.TransactionPhase;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.notification.outbox.application.service.NotificationDispatchService;
import net.civeira.phylax.features.notification.outbox.domain.event.UrgentMessageEnqueuedEvent;

/**
 * Triggers an immediate dispatch cycle when an urgent outbox message is committed.
 *
 * <p>
 * The observer fires with {@link TransactionPhase#AFTER_SUCCESS}, which guarantees that the message
 * is already visible in the database before {@link NotificationDispatchService#dispatch()} is
 * called in its own new transaction.
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class UrgentMessageDispatchObserver {

  private final NotificationDispatchService dispatchService;

  /**
   * Handles the urgent-message event by triggering an out-of-schedule dispatch cycle.
   *
   * @param event the event carrying the uid of the newly committed urgent message
   */
  public void onUrgentMessage(
      @Observes(during = TransactionPhase.AFTER_SUCCESS) UrgentMessageEnqueuedEvent event) {
    log.debug("Urgent message uid={} committed, triggering immediate dispatch", event.messageUid());
    try {
      dispatchService.dispatch();
    } catch (Exception e) {
      log.warn("Immediate dispatch for urgent message uid={} failed", event.messageUid(), e);
    }
  }
}
